            sectionSourceReferences = listOf("what", "purpose", "during", "method", "preparation", "after", "important", "questions").associateWith { listOf(vitrectomy.reference) },
            relatedQuestions = listOf(
                ProcedureRelatedQuestion("vitrectomia-que", "¿Qué parte del ojo se retira durante una vitrectomía?", "what"),
                ProcedureRelatedQuestion("vitrectomia-gas", "¿Qué debemos saber si colocan una burbuja de gas?", "bubble"),
                ProcedureRelatedQuestion("vitrectomia-catarata", "¿En qué se diferencia de la cirugía de cataratas?", "comparison"),
