            sectionSourceReferences = listOf("what", "purpose", "during", "method", "preparation", "after", "important", "questions").associateWith { listOf(biopsy.reference) },
            relatedQuestions = listOf(
                ProcedureRelatedQuestion("biopsia-renal-que", "¿Qué se examina en una biopsia renal?", "what"),
                ProcedureRelatedQuestion("biopsia-renal-como", "¿Cómo suele obtenerse la muestra?", "during"),
                ProcedureRelatedQuestion("biopsia-renal-riesgo", "¿Qué información conviene comunicar antes de la biopsia?", "preparation"),
                ProcedureRelatedQuestion("biopsia-renal-despues", "¿Qué vigilan después de obtener la muestra?", "after"),
